                          double *sigmar, double *sigmai);

/* Import ARNAUD symbols from the already-loaded scipy extension. */
static int load_arnaud(void) {
    static int loaded = 0;
    if (loaded) return 0;
    PyObject *mod = PyImport_ImportModule(
        "scipy.sparse.linalg._eigen.arpack._arpacklib");
    if (mod == NULL) return -1;
    Py_DECREF(mod);
    loaded = 1;
    return 0;
}

static void csr_matvec(int n, const int32_t *indptr, const int32_t *indices,
                       const double *data, const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        int32_t start = indptr[i];
        int32_t end = indptr[i + 1];
        double sum = 0.0;
        int32_t j = start;
        /* 4-way unroll for the typical ~10 nnz/row */
        for (; j + 3 < end; j += 4) {
            sum += data[j] * x[indices[j]];
            sum += data[j + 1] * x[indices[j + 1]];
            sum += data[j + 2] * x[indices[j + 2]];
            sum += data[j + 3] * x[indices[j + 3]];
        }
        for (; j < end; j++) {
            sum += data[j] * x[indices[j]];
        }
        y[i] = sum;
    }
}

/*
 * solve(indptr, indices, data, v0, k, ncv, maxiter, tol) -> (dr, di, z)
 * dr, di: length k+1 float64 (real/imag eigenvalue parts, ARPACK layout)
 * z: length n*(k+1) float64, Fortran order (column-major), real eigenvector
 *    storage exactly as ARPACK dneupd returns it.
 * Returns None-equivalent via exception on failure.
 */
static PyObject *solve(PyObject *self, PyObject *args) {
    PyObject *indptr_obj, *indices_obj, *data_obj, *v0_obj;
    int k, ncv, maxiter;
    double tol;
    if (!PyArg_ParseTuple(args, "OOOOiiid", &indptr_obj, &indices_obj,
                          &data_obj, &v0_obj, &k, &ncv, &maxiter, &tol)) {
        return NULL;
    }
    if (load_arnaud() != 0) return NULL;

    Py_buffer indptr_buf, indices_buf, data_buf, v0_buf;
    memset(&indptr_buf, 0, sizeof(indptr_buf));
    memset(&indices_buf, 0, sizeof(indices_buf));
    memset(&data_buf, 0, sizeof(data_buf));
    memset(&v0_buf, 0, sizeof(v0_buf));

    if (PyObject_GetBuffer(indptr_obj, &indptr_buf, PyBUF_SIMPLE) != 0) return NULL;
    if (PyObject_GetBuffer(indices_obj, &indices_buf, PyBUF_SIMPLE) != 0) {
        PyBuffer_Release(&indptr_buf); return NULL;
    }
    if (PyObject_GetBuffer(data_obj, &data_buf, PyBUF_SIMPLE) != 0) {
        PyBuffer_Release(&indices_buf); PyBuffer_Release(&indptr_buf); return NULL;
    }
    if (PyObject_GetBuffer(v0_obj, &v0_buf, PyBUF_SIMPLE) != 0) {
        PyBuffer_Release(&data_buf); PyBuffer_Release(&indices_buf);
        PyBuffer_Release(&indptr_buf); return NULL;
    }

    int n = (int)(v0_buf.len / (Py_ssize_t)sizeof(double));
    const int32_t *indptr = (const int32_t *)indptr_buf.buf;
    const int32_t *indices = (const int32_t *)indices_buf.buf;
    const double *adata = (const double *)data_buf.buf;

    arnaud_state_d st;
    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.which = 0;     /* LM */
    st.ido = 0;
    st.info = 1;      /* resid supplied */
    st.bmat = 0;      /* standard problem */
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    double *resid = (double *)malloc(sizeof(double) * (size_t)n);
    double *v = (double *)calloc((size_t)n * (size_t)ncv, sizeof(double));
    double *workd = (double *)calloc(3 * (size_t)n, sizeof(double));
    double *workl = (double *)calloc(3 * (size_t)ncv * (size_t)(ncv + 2), sizeof(double));
    int32_t *ipntr = (int32_t *)calloc(14, sizeof(int32_t));

    if (!resid || !v || !workd || !workl || !ipntr) {
        PyErr_NoMemory();
        goto cleanup_fail;
    }
    memcpy(resid, v0_buf.buf, sizeof(double) * (size_t)n);

    int info_out = 0;
    for (;;) {
        ARNAUD_dnaupd(&st, resid, v, ipntr, workd, workl);
        int ido = st.ido;
        if (ido == 1 || ido == 5) {
            int xoff = ipntr[0] - 1;
            int yoff = ipntr[1] - 1;
            csr_matvec(n, indptr, indices, adata, workd + xoff, workd + yoff);
        } else if (ido == 2) {
            int xoff = ipntr[0] - 1;
            int yoff = ipntr[1] - 1;
            memcpy(workd + yoff, workd + xoff, sizeof(double) * (size_t)n);
        } else if (ido == 4) {
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else if (ido == 3) {
            PyErr_SetString(PyExc_RuntimeError, "ARPACK requested user shifts");
            goto cleanup_fail;
        } else {
            info_out = st.info;
            break;
        }
    }

    if (info_out != 0) {
        PyErr_Format(PyExc_RuntimeError,
                     "ARPACK dnaupd info=%d iters=%d nconv=%d",
                     info_out, st.iter, st.nconv);
        goto cleanup_fail;
    }

    int32_t *sselect = (int32_t *)calloc((size_t)ncv, sizeof(int32_t));
    double *dr = (double *)calloc((size_t)k + 1, sizeof(double));
    double *di = (double *)calloc((size_t)k + 1, sizeof(double));
    double *z = (double *)calloc((size_t)n * ((size_t)k + 1), sizeof(double));
    double *workev = (double *)calloc(3 * (size_t)ncv, sizeof(double));
    if (!sselect || !dr || !di || !z || !workev) {
        free(sselect); free(dr); free(di); free(z); free(workev);
        PyErr_NoMemory();
        goto cleanup_fail;
    }
    double sigmar = 0.0, sigmai = 0.0;
    st.info = 0;
    ARNAUD_dneupd(&st, 1, 0, sselect, dr, di, z, workev, resid, v, ipntr,
                  workd, workl, &sigmar, &sigmai);
    int ierr = st.info;
    free(sselect);
    free(workev);
    if (ierr != 0) {
        free(dr); free(di); free(z);
        PyErr_Format(PyExc_RuntimeError, "ARPACK dneupd info=%d", ierr);
        goto cleanup_fail;
    }

    /* Hand the raw arrays back as Python bytes; the caller interprets them. */
    PyObject *dr_b = PyBytes_FromStringAndSize((char *)dr, sizeof(double) * ((size_t)k + 1));
    PyObject *di_b = PyBytes_FromStringAndSize((char *)di, sizeof(double) * ((size_t)k + 1));
    PyObject *z_b = PyBytes_FromStringAndSize((char *)z, sizeof(double) * (size_t)n * ((size_t)k + 1));
    free(dr); free(di); free(z);

    free(resid); free(v); free(workd); free(workl); free(ipntr);
    PyBuffer_Release(&v0_buf); PyBuffer_Release(&data_buf);
    PyBuffer_Release(&indices_buf); PyBuffer_Release(&indptr_buf);

    if (!dr_b || !di_b || !z_b) {
        Py_XDECREF(dr_b); Py_XDECREF(di_b); Py_XDECREF(z_b);
        return NULL;
    }
    return Py_BuildValue("NNN", dr_b, di_b, z_b);

cleanup_fail:
    free(resid); free(v); free(workd); free(workl); free(ipntr);
    PyBuffer_Release(&v0_buf); PyBuffer_Release(&data_buf);
    PyBuffer_Release(&indices_buf); PyBuffer_Release(&indptr_buf);
    return NULL;
}

static PyMethodDef methods[] = {
    {"solve", solve, METH_VARARGS, "Leading eigenpairs via direct ARNAUD."},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastar", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_fastar(void) { return PyModule_Create(&moduledef); }
